import{_ as n,W as p,s as o,u as d,ah as c,I as l,w as s,Z as t,A as i}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const f=JSON.parse('{"title":"检查系统和硬件信息的命令 | LCTT x X-CMD","titleTemplate":false,"description":"检查系统和硬件信息的命令 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"检查系统和硬件信息的命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"检查系统和硬件信息的命令 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170515 Commands to check System & Hardware Information","title":"检查系统和硬件信息的命令","tag":"201801"},"relativePath":"201801/20170515 Commands to check System & Hardware Information.md","filePath":"[post].md"}'),r={name:"201801/20170515 Commands to check System & Hardware Information.md"};function h(m,a,u,b,g,C){const e=p("Link");return d(),o("div",null,[a[18]||(a[18]=c('<h1 id="检查系统和硬件信息的命令" tabindex="-1">检查系统和硬件信息的命令 <a class="header-anchor" href="#检查系统和硬件信息的命令" aria-label="Permalink to 检查系统和硬件信息的命令">​</a></h1><p>你们好，Linux 爱好者们，在这篇文章中，我将讨论一些作为系统管理员重要的事。众所周知，作为一名优秀的系统管理员意味着要了解有关 IT 基础架构的所有信息，并掌握有关服务器的所有信息，无论是硬件还是操作系统。所以下面的命令将帮助你了解所有的硬件和系统信息。</p><h3 id="_1-查看系统信息" tabindex="-1">1 查看系统信息 <a class="header-anchor" href="#_1-查看系统信息" aria-label="Permalink to 1 查看系统信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ uname -a</span></span></code></pre></div><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/uname.jpg?resize=664%2C69" alt="uname command"></p><p>它会为你提供有关系统的所有信息。它会为你提供系统的内核名、主机名、内核版本、内核发布号、硬件名称。</p><h3 id="_2-查看硬件信息" tabindex="-1">2 查看硬件信息 <a class="header-anchor" href="#_2-查看硬件信息" aria-label="Permalink to 2 查看硬件信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lshw</span></span></code></pre></div><p><img src="https://i2.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lshw.jpg?resize=641%2C386" alt="lshw command"></p><p>使用 <code>lshw</code> 将在屏幕上显示所有硬件信息。</p><h3 id="_3-查看块设备-硬盘、闪存驱动器-信息" tabindex="-1">3 查看块设备（硬盘、闪存驱动器）信息 <a class="header-anchor" href="#_3-查看块设备-硬盘、闪存驱动器-信息" aria-label="Permalink to 3 查看块设备（硬盘、闪存驱动器）信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lsblk</span></span></code></pre></div><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lsblk.jpg?resize=646%2C162" alt="lsblk command"></p><p><code>lsblk</code> 命令在屏幕上打印关于块设备的所有信息。使用 <code>lsblk -a</code> 可以显示所有块设备。</p><h3 id="_4-查看-cpu-信息" tabindex="-1">4 查看 CPU 信息 <a class="header-anchor" href="#_4-查看-cpu-信息" aria-label="Permalink to 4 查看 CPU 信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lscpu</span></span></code></pre></div><p><img src="https://i2.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lscpu.jpg?resize=643%2C216" alt="lscpu command"></p><p><code>lscpu</code> 在屏幕上显示所有 CPU 信息。</p><h3 id="_5-查看-pci-信息" tabindex="-1">5 查看 PCI 信息 <a class="header-anchor" href="#_5-查看-pci-信息" aria-label="Permalink to 5 查看 PCI 信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lspci</span></span></code></pre></div><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lspci.jpg?resize=644%2C238" alt="lspci command"></p><p>所有的网络适配器卡、USB 卡、图形卡都被称为 PCI。要查看他们的信息使用 <code>lspci</code>。</p><p><code>lspci -v</code> 将提供有关 PCI 卡的详细信息。</p><p><code>lspci -t</code> 会以树形格式显示它们。</p><h3 id="_6-查看-usb-信息" tabindex="-1">6 查看 USB 信息 <a class="header-anchor" href="#_6-查看-usb-信息" aria-label="Permalink to 6 查看 USB 信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lsusb</span></span></code></pre></div><p><img src="https://i2.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lsusb.jpg?resize=645%2C37" alt="lsusb command"></p><p>要查看有关连接到机器的所有 USB 控制器和设备的信息，我们使用 <code>lsusb</code>。</p><h3 id="_7-查看-scsi-信息" tabindex="-1">7 查看 SCSI 信息 <a class="header-anchor" href="#_7-查看-scsi-信息" aria-label="Permalink to 7 查看 SCSI 信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lsscsi</span></span></code></pre></div><p><img src="https://i2.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/lsscsi.jpg?resize=639%2C110" alt="lsscsi"></p><p>要查看 SCSI 信息输入 <code>lsscsi</code>。<code>lsscsi -s</code> 会显示分区的大小。</p><h3 id="_8-查看文件系统信息" tabindex="-1">8 查看文件系统信息 <a class="header-anchor" href="#_8-查看文件系统信息" aria-label="Permalink to 8 查看文件系统信息">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ fdisk -l</span></span></code></pre></div><p><img src="https://i2.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/fdisk.jpg?resize=656%2C335" alt="fdisk command"></p><p>使用 <code>fdisk -l</code> 将显示有关文件系统的信息。虽然 <code>fdisk</code> 的主要功能是修改文件系统，但是也可以创建新分区，删除旧分区（详情在我以后的教程中）。</p>',36)),l("p",null,[a[2]||(a[2]=s("就是这些了，我的 Linux 爱好者们。建议你在**")),t(e,{href:"http://linuxtechlab.com/linux-commands-beginners-part-1/"},{default:i(()=>a[0]||(a[0]=[s("这里")])),_:1}),a[3]||(a[3]=l("strong",null,"和",-1)),t(e,{href:"http://linuxtechlab.com/linux-commands-beginners-part-2/"},{default:i(()=>a[1]||(a[1]=[s("这里")])),_:1}),a[4]||(a[4]=s("**的文章中查看关于另外的 Linux 命令。"))]),a[19]||(a[19]=l("hr",null,null,-1)),l("p",null,[a[6]||(a[6]=s("via: ")),t(e,{href:"http://linuxtechlab.com/commands-system-hardware-info/"},{default:i(()=>a[5]||(a[5]=[s("http://linuxtechlab.com/commands-system-hardware-info/")])),_:1})]),l("p",null,[a[10]||(a[10]=s("作者：")),t(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:i(()=>a[7]||(a[7]=[s("Shusain")])),_:1}),a[11]||(a[11]=s(" 译者：")),t(e,{href:"https://github.com/geekpi"},{default:i(()=>a[8]||(a[8]=[s("geekpi")])),_:1}),a[12]||(a[12]=s(" 校对：")),t(e,{href:"https://github.com/wxy"},{default:i(()=>a[9]||(a[9]=[s("wxy")])),_:1})]),l("p",null,[a[15]||(a[15]=s("本文由 ")),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>a[13]||(a[13]=[s("LCTT")])),_:1}),a[16]||(a[16]=s(" 原创编译，")),t(e,{href:"https://linux.cn/"},{default:i(()=>a[14]||(a[14]=[s("Linux中国")])),_:1}),a[17]||(a[17]=s(" 荣誉推出"))])])}const v=n(r,[["render",h]]);export{f as __pageData,v as default};
